# ==============================================================================
# DEPLOYMENT NOTE — VERCEL / SERVERLESS VERSION
# ------------------------------------------------------------------------------
# Vercel functions are stateless: no persistent background thread, and
# module globals can reset between cold starts. Differences from the Pi
# build (apaw_app.py), which is the real field-deployment target:
#   - Sensor history is a deterministic smooth wave keyed to server time,
#     not a real rolling buffer — looks identical on screen, updates every
#     poll, but isn't a true log.
#   - No SQLite persistence and no MQTT client here — neither fits a
#     stateless serverless function. The LoRaWAN HTTP webhook below still
#     works statelessly (updates in-memory globals for the current warm
#     instance), which is fine for a live demo but not for production.
#   - Node config / threshold edits and resident reports are plain
#     globals — fine within one demo session (Vercel keeps the function
#     warm across your requests), not durable across a cold start.
# ==============================================================================

SIMULATION_MODE = "normal"
HISTORY_LEN = 12
METRICS = ["water_level", "water_flow", "rainfall", "temperature", "humidity"]

