import json as _json

def build_api_payload():
    status = current_status()
    tiers = {nid: risk_tier(status[nid]["water_level"]) for nid in ALL_TABS}
    hist_out = {nid: get_history(nid) for nid in ALL_TABS}
    hist_times_out = {nid: node_history_times_fmt(nid) for nid in ALL_TABS}
    eta_out = {nid: eta_minutes_to_high(nid) if nid != "main" else eta_minutes_to_high(
        max(NODE_ORDER, key=lambda n: status[n]["water_level"])
    ) for nid in ALL_TABS}
    return {
        "status": status,
        "tier": tiers,
        "tier_color": TIER_COLOR,
        "history": hist_out,
        "history_times": hist_times_out,
        "eta": eta_out,
        "data_source": data_source,
        "prediction": compute_ai_prediction(status),
        "alerts": synth_alerts(status)
    }

@app.route('/')
def dashboard():
    active = request.args.get('node', 'main')
    if active not in ALL_TABS:
        active = 'main'
    status = current_status()
    tiers = {nid: risk_tier(status[nid]["water_level"]) for nid in NODE_ORDER}
    tier_color_by_node = {nid: TIER_COLOR[tiers[nid]] for nid in NODE_ORDER}
    tier_color_by_node["main"] = TIER_COLOR[risk_tier(status["main"]["water_level"])]
    return render_template_string(
        DASHBOARD_HTML,
        status=status,
        active=active,
        meta=ALL_META,
        hq=HQ_META,
        node_order=NODE_ORDER,
        tabs=ALL_TABS,
        tier_color=tier_color_by_node,
        reports=resident_reports,
        alerts=synth_alerts(status),
        prediction=compute_ai_prediction(status),
        data_source=data_source,
        meta_json=_json.dumps(ALL_META),
        logo_b64=LOGO_B64
    )

