# ==============================================================================
# LoRaWAN webhook — same contract as the Pi build. Works statelessly here:
# updates in-memory globals for the current warm instance. Fine for a demo
# session; not durable. No MQTT client on Vercel — doesn't fit a stateless
# function (needs a persistent connection). Use the Pi build for that.
# ==============================================================================
@app.route('/webhook/lorawan', methods=['POST'])
def lorawan_webhook():
    import time as _time
    payload = request.get_json(silent=True)
    if not payload:
        return jsonify({"ok": False, "error": "expected JSON body"}), 400
    node_id = payload.get("node_id")
    if not node_id or node_id not in NODE_ORDER:
        return jsonify({"ok": False, "error": "missing/unknown node_id"}), 400
    base = synth_reading(node_id)
    reading = dict(base)
    for k in METRICS:
        if k in payload:
            reading[k] = round(float(payload[k]), 2)
    reading["timestamp"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    reading["risk_level"] = "Critical" if risk_tier(reading["water_level"]) == "high" else "Normal"
    _real_overrides[node_id] = reading
    _last_real_update[node_id] = _time.time()
    data_source[node_id] = "lorawan-live"
    return jsonify({"ok": True, "node_id": node_id, "applied": reading})

@app.route('/api/config/node/<node_id>', methods=['POST'])
def update_node_config(node_id):
    if node_id not in NODE_META:
        return jsonify({"ok": False, "error": "unknown node_id"}), 400
    payload = request.get_json(silent=True) or {}
    if "label" in payload:
        NODE_META[node_id]["label"] = str(payload["label"])[:60]
    if "lat" in payload:
        NODE_META[node_id]["lat"] = float(payload["lat"])
    if "lng" in payload:
        NODE_META[node_id]["lng"] = float(payload["lng"])
    ALL_META[node_id] = NODE_META[node_id]
    return jsonify({"ok": True, "node": NODE_META[node_id]})

@app.route('/api/config/thresholds', methods=['POST'])
def update_thresholds():
    payload = request.get_json(silent=True) or {}
    try:
        medium = float(payload.get("medium", RISK_THRESHOLDS["medium"]))
        high = float(payload.get("high", RISK_THRESHOLDS["high"]))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "medium/high must be numbers"}), 400
    if medium >= high:
        return jsonify({"ok": False, "error": "medium threshold must be less than high threshold"}), 400
    RISK_THRESHOLDS["medium"] = medium
    RISK_THRESHOLDS["high"] = high
    return jsonify({"ok": True, "thresholds": RISK_THRESHOLDS})

@app.route('/api/system')
def system_stats():
    stats = {"cpu_percent": None, "memory_percent": None, "memory_used_mb": None,
              "memory_total_mb": None, "disk_percent": None, "disk_free_gb": None,
              "db_size_mb": None, "note": "Running on Vercel serverless — no persistent disk/DB here. These stats reflect the ephemeral function container, not your Pi. Use the Pi build's /api/system for real hardware numbers."}
    try:
        import psutil
        stats["cpu_percent"] = psutil.cpu_percent(interval=0.2)
        vm = psutil.virtual_memory()
        stats["memory_percent"] = vm.percent
        stats["memory_used_mb"] = round(vm.used / (1024 * 1024), 1)
        stats["memory_total_mb"] = round(vm.total / (1024 * 1024), 1)
    except ImportError:
        pass
    return jsonify(stats)

